import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="auth-page">
      <div class="auth-card">
        <div class="auth-header">
          <h1>Đăng nhập</h1>
          <p>Chào mừng bạn quay trở lại!</p>
        </div>
        <form (ngSubmit)="onSubmit()">
          <div class="form-group">
            <label>Email</label>
            <input type="email" class="form-control" [(ngModel)]="email" name="email" required placeholder="Nhập email của bạn">
          </div>
          <div class="form-group">
            <label>Mật khẩu</label>
            <input type="password" class="form-control" [(ngModel)]="password" name="password" required placeholder="Nhập mật khẩu">
          </div>
          <div class="form-error" *ngIf="error">{{ error }}</div>
          <button type="submit" class="btn btn-primary btn-lg" style="width:100%;" [disabled]="loading">
            {{ loading ? 'Đang đăng nhập...' : 'Đăng nhập' }}
          </button>
        </form>
        <div class="auth-footer">
          <p>Chưa có tài khoản? <a routerLink="/auth/register">Đăng ký ngay</a></p>
        </div>
        <div class="demo-accounts">
          <p><strong>Demo accounts:</strong></p>
          <p>Admin: admin&#64;webquangbadulich.com / admin123</p>
          <p>User: user&#64;webquangbadulich.com / user123</p>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .auth-page { min-height: 80vh; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 2rem; }
    .auth-card { background: white; border-radius: 16px; padding: 2.5rem; width: 100%; max-width: 440px; box-shadow: 0 20px 60px rgba(0,0,0,0.2); }
    .auth-header { text-align: center; margin-bottom: 2rem; h1 { margin-bottom: 0.25rem; } p { color: var(--gray); margin: 0; } }
    .auth-footer { text-align: center; margin-top: 1.5rem; p { color: var(--gray); margin: 0; } }
    .demo-accounts { margin-top: 1.5rem; padding: 1rem; background: #f8fafc; border-radius: 8px; font-size: 0.875rem; color: var(--gray); p { margin: 0.25rem 0; } }
  `]
})
export class LoginComponent {
  email = '';
  password = '';
  error = '';
  loading = false;

  constructor(private api: ApiService, private auth: AuthService, private router: Router) {}

  onSubmit() {
    if (!this.email || !this.password) return;
    this.loading = true;
    this.error = '';
    this.api.login({ email: this.email, password: this.password }).subscribe({
      next: (res) => {
        this.auth.login(res.token, res.user);
        this.loading = false;
        this.router.navigate(['/']);
      },
      error: (err) => {
        this.error = err.error?.error || 'Đăng nhập thất bại';
        this.loading = false;
      }
    });
  }
}
